diff --git a/client.mjs b/client.mjs
index 9ad81d0..8406edb 100644
--- a/client.mjs
+++ b/client.mjs
@@ -2,0 +3,5 @@
+import { sleep as realSleep } from './util.mjs';
+
+const RETRIES = 3;
+const BASE_DELAY_MS = 100;
+
@@ -12,4 +17,16 @@ export class HttpError extends Error {
-export async function fetchJson(url, { fetch = globalThis.fetch, headers = {} } = {}) {
-  const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
-  if (!res.ok) throw new HttpError(res.status, url);
-  return res.json();
+// Retries transient failures (503, or a dropped connection, which fetch reports as TypeError)
+// up to RETRIES times with exponential backoff. `sleep` is injectable so tests don't wait.
+export async function fetchJson(url, { fetch = globalThis.fetch, sleep = realSleep, headers = {} } = {}) {
+  for (let attempt = 0; ; attempt++) {
+    let res;
+    try {
+      res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+    } catch (err) {
+      if (!(err instanceof TypeError) || attempt >= RETRIES) throw err;
+      await sleep(BASE_DELAY_MS * 2 ** attempt);
+      continue;
+    }
+    if (res.ok) return res.json();
+    if (res.status !== 503 || attempt >= RETRIES) throw new HttpError(res.status, url);
+    await sleep(BASE_DELAY_MS * 2 ** attempt);
+  }
