-  const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
-  if (!res.ok) throw new HttpError(res.status, url);
-  return res.json();
+const RETRIES = 3;
+const BASE_DELAY_MS = 100;
+
+// Retries 503s and dropped connections (fetch rejecting) up to RETRIES times with
+// exponential backoff. Other statuses, including all 4xx, fail immediately.
+// `sleep` is injectable so tests don't wait.
+export async function fetchJson(url, { fetch = globalThis.fetch, headers = {}, sleep = realSleep } = {}) {
+  for (let attempt = 0; ; attempt++) {
+    const canRetry = attempt < RETRIES;
+    let res;
+    try {
+      res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+    } catch (err) {
+      if (!canRetry || err?.name === 'AbortError') throw err;
+      await sleep(BASE_DELAY_MS * 2 ** attempt);
+      continue;
+    }
+    if (res.ok) return res.json();
+    if (res.status !== 503 || !canRetry) throw new HttpError(res.status, url);
+    await sleep(BASE_DELAY_MS * 2 ** attempt);
+  }
