+// Retries 5xx responses and dropped connections (fetch rejecting) up to RETRIES times
+// with exponential backoff. 4xx is never retried. `sleep` is injectable so tests don't wait.
+export async function fetchJson(url, { fetch = globalThis.fetch, sleep = realSleep, headers = {} } = {}) {
+  for (let attempt = 0; ; attempt++) {
+    let res;
+    try {
+      res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+    } catch (err) {
+      if (attempt >= RETRIES || err?.name === 'AbortError') throw err;
+      await sleep(BASE_DELAY_MS * 2 ** attempt);
+      continue;
