+  assert.equal(calls, 1);
+  assert.deepEqual(naps, []);
+});
+
+test('retries 503 and dropped connections with backoff, then succeeds', async () => {
+  const script = [() => respond(503), () => { throw new TypeError('fetch failed'); }, () => respond(200, { sku: 'A1' })];
+  const fetch = async () => script.shift()();
+  const naps = [];
+  assert.deepEqual(await fetchJson('https://x/items/A1', { fetch, sleep: async (ms) => naps.push(ms) }), { sku: 'A1' });
+  assert.deepEqual(naps, [200, 400]);
+});
+
